create or replace function public.send_owner_mission_message(p_job_id uuid,p_body text,p_target text) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_actor uuid:=auth.uid(); v_agency uuid; v_guard uuid; v_id uuid; begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; if nullif(trim(p_body),'') is null then raise exception 'MESSAGE_REQUIRED'; end if; if p_target not in ('agency','guard') then raise exception 'INVALID_TARGET'; end if; select j.accepted_agency_id,ja.guard_id into v_agency,v_guard from public.marketplace_jobs j left join public.job_assignments ja on ja.job_id=j.id where j.id=p_job_id; if v_agency is null then raise exception 'MISSION_HAS_NO_AGENCY'; end if; if p_target='guard' and v_guard is null then raise exception 'MISSION_HAS_NO_GUARD'; end if; insert into public.agency_messages(agency_id,job_id,sender_user_id,sender_role,channel,body,sender_guard_id,recipient_guard_id) values(v_agency,p_job_id,v_actor,'system','active_mission',trim(p_body),null,case when p_target='guard' then v_guard else null end) returning id into v_id; insert into public.mission_events(job_id,event_type,payload,actor_user_id) values(p_job_id,'owner_message_sent',jsonb_build_object('message_id',v_id,'target',p_target),v_actor); insert into public.owner_audit_log(actor_user_id,action,entity_type,entity_id,metadata) values(v_actor,'owner_mission_message_sent','marketplace_job',p_job_id,jsonb_build_object('message_id',v_id,'target',p_target)); return jsonb_build_object('id',v_id,'target',p_target,'delivered',true); end $$; revoke all on function public.send_owner_mission_message(uuid,text,text) from public,anon; grant execute on function public.send_owner_mission_message(uuid,text,text) to authenticated;
